class Report {
    private final Writer out;

    Report(Writer out) {
        this.out = out;
    }

    @Override
    protected void finalize() throws Throwable {
        out.close();
    }
}

static final List<String> LOG = new ArrayList<>();

static int run() {
    try {
        LOG.add("started");
        return LOG.size();
    } finally {
        LOG.add("done");
    }
}

// caller
System.out.println(run() + " " + LOG);

